from pathlib import Path
import argparse,json,hashlib,shutil,pandas as pd
p=argparse.ArgumentParser();p.add_argument('--review',required=True);p.add_argument('--normalized',required=True);a=p.parse_args();h=Path(a.review);n=Path(a.normalized);sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest();r=json.loads((h/'audit.json').read_text());assert r['all_checks_passed'] and r['accepted_units_sha256']==sha(n/'normalized_units.parquet');u=pd.read_parquet(n/'normalized_units.parquet',columns=['resolution_index']);assert u.resolution_index.isna().all();shutil.copyfile(Path(__file__).with_name('audit.py'),h/'audit_code_frozen.py');(h/'resolution_index_addendum.json').write_text(json.dumps({'status':'ACCEPTED_RAW_RESOLUTION_INDEX_PRESERVATION','all_checks_passed':True,'n_units':len(u),'all_resolution_index_NA':True,'source_normalized_units_sha256':sha(n/'normalized_units.parquet'),'audit_sha256':sha(h/'audit.json')},indent=2));m=h/'review_freeze_manifest.json';assert not m.exists();m.write_text(json.dumps({'files':{f.name:sha(f)for f in h.iterdir()if f.is_file()}},indent=2));print(sha(h/'audit.json'))
